'use strict';

import { createError, MISSING_DOC } from 'pouchdb-errors';

import { DOC_STORE, META_STORE } from './util';

import { latest as getLatest } from 'pouchdb-merge';

export default function (txn, id, callback) {
  const opts = {}; // FIXME remove opts
  console.log('indexeddb._getLocal()', 'id:', id, 'opts:', JSON.stringify(opts), 'callback:', typeof callback);

  if (txn.error) {
    return callback(txn.error);
  }

  const docStore = id.startsWith('_local/') ? META_STORE : DOC_STORE; // FIXME always use META_STORE

  console.log('indexeddb._getLocal()', 'docStore:', docStore);

  txn.txn.objectStore(docStore).get(id).onsuccess = function (e) {
    var doc = e.target.result;
    var rev;

    console.log('indexeddb._getLocal()', 'doc:', JSON.stringify(doc));

    if (!opts.rev) {
      rev = (doc && doc.rev);
    } else {
      rev = opts.latest ? getLatest(opts.rev, doc) : opts.rev;
    }

    console.log('indexeddb._getLocal()', 'rev:', rev);

    if (!doc || (doc.deleted && !opts.rev) || !(rev in doc.revs)) { // TODO shouldn't need to check doc.deleted or rev in doc.revs, cuz there's no opts
      console.log('indexeddb._getLocal()', 'returning:', 'error:MISSING_DOC');
      callback(createError(MISSING_DOC, 'missing'));
      return;
    }

    console.log('indexeddb._getLocal()', 'getting result data...');

    var result = doc.revs[rev].data;
    result._id = doc.id;
    result._rev = rev;

    console.log('indexeddb._getLocal()', 'returning:', {
      doc: result,
      metadata: doc,
      ctx: txn
    });

    // WARNING: expecting possible old format
    // TODO: why are we passing the transaction in the context?
    //       It's not clear we ever thread these txns usefully
    callback(null, {
      doc: result,
      metadata: doc,
      ctx: txn
    });
  };
}
